function validate([year, month]) {
  if (!Number.isInteger(year) || year < 1583 || year > 2100) return 'year must be a whole number from 1583 to 2100.';
  if (!Number.isInteger(month) || month < 1 || month > 12) return 'month must be a whole number from 1 to 12.';
  return null;
}

